from collections import deque
from typing import List

def fantasy_card_duel(playerDeckA: List[int], playerDeckB: List[int], max_rounds: int = 10**6) -> int:
    a, b = deque(playerDeckA), deque(playerDeckB)
    rounds = 0
    while a and b and rounds < max_rounds:
        rounds += 1
        x, y = a.popleft(), b.popleft()
        if x > y:
            a.extend((y, x))        # 赢家把对方的牌先压到底，再压自己的
        elif y > x:
            b.extend((x, y))
        else:
            a.append(x)             # 平局各自收回
            b.append(y)
    return rounds if not a or not b else -1   # -1：超过上限仍未结束（可能循环）
